void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec3 dir = normalize(vec3(fragCoord / iResolution.xy * 2.0 - 1.0, 1));
    dir.x *= iResolution.x / iResolution.y;
    vec3 pos = vec3(0, 0.5, -5);

    float ry = radians(iTime * 10.0);
    mat3 rm = mat3(cos(ry), 0, sin(ry), 0, 1, 0, -sin(ry), 0, cos(ry));
    dir *= rm;
    pos *= rm;

    float r = 1.0;
    float rDisk = 3.0;

    const int steps = 1024;
    const float ss = 0.01;

    vec3 col;

    int i;
    for (i = 0; i < steps; i++) {
        pos += ss * dir;
        dir += ss * normalize(-pos) / dot(pos, pos);
        if (length(pos) <= r) {
            col = vec3(0);
            break;
        }
        if (length(pos.xz) <= rDisk && abs(pos.y) < 0.005) {
            col = mix(vec3(1, 0, 0), vec3(1, 1, 0), texture(iChannel1, vec2(degrees(atan(pos.z, pos.x)) / 90.0, length(pos.xz))).xxx);
            break;
        }
    }
    if (i == steps) {
        col = texture(iChannel0, dir).rgb;
    }

    fragColor = vec4(col, 1);
}

void mainCubemap(out vec4 fragColor, in vec2 fragCoord, in vec3 rayOri, in vec3 rayDir) {
    vec3 col = vec3(0);

    vec2 pos = vec2(degrees(atan(rayDir.z, rayDir.x)) / 360.0, rayDir.y);

    if (dot(rayDir, normalize(texture(iChannel0, pos).xyz * 2.0 - 1.0)) > 0.99) {
        col = vec3(1);
    }

    fragColor = vec4(col, 1);
}
